<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { api, download, errorText } from "../api";
import { usePlatformStore } from "../stores/platform";
import DataTable from "../components/DataTable.vue";
const store = usePlatformStore(); const profile = ref<Record<string, any> | null>(null); const toolHealth = ref<Record<string, any> | null>(null); const history = ref<Record<string, any>[]>([]); const diff = ref<Record<string, any> | null>(null); const rules = ref<Record<string, any>[]>([]); const jobs = ref<Record<string, any>[]>([]); const report = ref<Record<string, any> | null>(null); const message = ref("");
const ruleDraft = reactive({ name: "", rule_id: "", severity: "medium", pattern: "", message: "", languages: ["python"] });
const packDraft = reactive({ name: "Project semantic rule pack", status: "draft", content: "rules:\n  - id: project.example.dangerous-eval\n    languages: [python]\n    severity: WARNING\n    message: Review dynamic evaluation.\n    pattern: eval(...)\n" });
const customDraft = reactive({ rule_id: "CUSTOM.PROJECT.PATTERN", title: "", severity: "medium", category: "custom", pattern: "", file_extensions: ".py,.ts", description: "", remediation: "", test_sample: "" });
const fixDraft = ref<Record<string, any> | null>(null);
const findingColumns = [{ key: "title", label: "问题" }, { key: "severity", label: "级别" }, { key: "file_path", label: "文件" }, { key: "line_start", label: "行" }, { key: "status", label: "整改状态" }, { key: "remediation_owner", label: "负责人" }];
async function load() { if (!store.project) return; const id = store.project.id; [profile.value, toolHealth.value, history.value, diff.value, report.value, jobs.value] = await Promise.all([api<Record<string, any>>(`/sast/projects/${id}/profile`).catch(() => null), api<Record<string, any>>("/sast/tool-health").catch(() => null), api<Record<string, any>[]>(`/sast/projects/${id}/scan-history`).catch(() => []), api<Record<string, any>>(`/sast/projects/${id}/scan-diff`).catch(() => null), api<Record<string, any>>(`/sast/projects/${id}/report`).catch(() => null), api<Record<string, any>[]>(`/scans?project_id=${id}`).catch(() => [])]); const packs: any = await api(`/sast/projects/${id}/semgrep-rules`).catch(() => ({ semgrep_rules: [] })); rules.value = packs.semgrep_rules ?? []; }
async function saveProfile() { if (!store.project || !profile.value) return; try { profile.value = await api(`/sast/projects/${store.project.id}/profile`, { method: "PATCH", body: JSON.stringify(profile.value) }); message.value = "SAST 配置已保存"; } catch (e) { message.value = errorText(e); } }
async function validateRule() { try { const r: any = await api("/sast/rules/validate", { method: "POST", body: JSON.stringify(ruleDraft) }); message.value = r.message ?? (r.valid ? "规则有效" : "规则无效"); } catch (e) { message.value = errorText(e); } }
async function createRule() { if (!store.project) return; try { profile.value = await api(`/sast/projects/${store.project.id}/rules`, { method: "POST", body: JSON.stringify(ruleDraft) }); message.value = "规则已保存"; await load(); } catch (e) { message.value = errorText(e); } }
async function queueJob() { if (!store.project) return; try { const job = await api<Record<string, any>>("/sast/jobs", { method: "POST", body: JSON.stringify({ project_id: store.project.id, source_path: store.sastPath, branch: store.project.default_branch }) }); jobs.value = [job, ...jobs.value]; message.value = "SAST Job 已排队。可启动本地 Worker，或点击“本次运行”由当前 API 进程执行。"; } catch (e) { message.value = `排队失败：${errorText(e)}`; } }
async function runJob(job: Record<string, any>) { try { await api(`/sast/jobs/${job.id}/run`, { method: "POST" }); message.value = "SAST Job 已完成，已生成独立扫描批次和报告。"; await load(); } catch (e) { message.value = `执行失败：${errorText(e)}`; await load(); } }
async function changeJob(job: Record<string, any>, action: "cancel" | "retry") { try { await api(`/scans/${job.id}/${action}`, { method: "POST" }); await load(); } catch (e) { message.value = `${action} 失败：${errorText(e)}`; } }
async function preflight(pack: Record<string, any>) { try { const result = await api<Record<string, any>>("/sast/semgrep-rules/preflight", { method: "POST", body: JSON.stringify({ content: pack.content }) }); message.value = `${pack.name}：${result.engine_status} · ${result.detail}`; } catch (e) { message.value = `预检失败：${errorText(e)}`; } }
async function publish(pack: Record<string, any>) { if (!store.project) return; try { await api(`/sast/projects/${store.project.id}/semgrep-rules/${pack.id}/publish`, { method: "POST" }); message.value = `${pack.name} 已发布。`; await load(); } catch (e) { message.value = `发布失败：${errorText(e)}`; } }
async function validatePack() { try { const result = await api<Record<string, any>>("/sast/semgrep-rules/validate", { method: "POST", body: JSON.stringify(packDraft) }); message.value = `YAML 结构有效：${result.yaml?.rule_count ?? 0} 条规则。`; } catch (e) { message.value = `YAML 校验失败：${errorText(e)}`; } }
async function savePack() { if (!store.project) return; try { await api(`/sast/projects/${store.project.id}/semgrep-rules`, { method: "POST", body: JSON.stringify(packDraft) }); message.value = packDraft.status === "draft" ? "YAML 规则包已保存为草稿。" : "YAML 规则包已发布。"; await load(); } catch (e) { message.value = `保存失败：${errorText(e)}`; } }
async function loadFixDraft(findingId: string) { try { fixDraft.value = await api(`/sast/findings/${findingId}/fix-draft`); message.value = ""; } catch (e) { message.value = `无法生成草案：${errorText(e)}`; } }
async function validateCustomRule() { try { const payload = { ...customDraft, file_extensions: customDraft.file_extensions.split(",").map(i => i.trim()).filter(Boolean) }; const result = await api<Record<string, any>>("/sast/rules/validate", { method: "POST", body: JSON.stringify(payload) }); message.value = result.message ?? "规则有效"; } catch (e) { message.value = `规则无效：${errorText(e)}`; } }
async function createCustomRule() { if (!store.project) return; try { const payload = { ...customDraft, file_extensions: customDraft.file_extensions.split(",").map(i => i.trim()).filter(Boolean) }; profile.value = await api(`/sast/projects/${store.project.id}/rules`, { method: "POST", body: JSON.stringify(payload) }); message.value = "项目自定义规则已保存。"; } catch (e) { message.value = `创建失败：${errorText(e)}`; } }
async function toggleCustomRule(rule: Record<string, any>) { if (!store.project) return; profile.value = await api(`/sast/projects/${store.project.id}/rules/${rule.id}`, { method: "PATCH", body: JSON.stringify({ enabled: !rule.enabled }) }); }
async function exportCiConfig() { if (!store.project) return; const config = await api<Record<string, any>>(`/sast/projects/${store.project.id}/ci-config`); const url = URL.createObjectURL(new Blob([JSON.stringify(config, null, 2)], { type: "application/json" })); const link = document.createElement("a"); link.href = url; link.download = `${store.project.name}-sast-ci-config.json`; link.click(); URL.revokeObjectURL(url); }
async function exportSarif() { if (!store.project) return; await download(`/sast/projects/${store.project.id}/sarif`, `${store.project.name}-sast.sarif`); }
onMounted(load);
</script>
<template><div class="stack-layout">
  <details class="advanced-details governance-advanced-details" open><summary>SAST 异步任务与可配置质量门禁</summary><div class="advanced-details-body"><section class="content-grid"><div class="panel full"><div class="panel-header"><h2>可追踪 SAST Job</h2><span>队列、进度、取消、重试和 Worker 入口</span></div><div class="filter-grid"><label class="wide-field">SAST 独立源码路径<input v-model="store.sastPath" /></label><button class="primary-action" :disabled="!store.sastPath.trim()" @click="queueJob">创建 SAST Job</button><button class="secondary-action" @click="load">刷新状态</button></div><p>常驻 Worker：<code>python scripts\sast_worker.py --max-jobs 0 --concurrency 1</code>。不启动 Worker 时，可对单个 Job 点击“本次运行”。</p><table v-if="jobs.length"><thead><tr><th>状态</th><th>阶段 / 进度</th><th>尝试</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs.filter(i=>i.scan_type==='sast_job')" :key="job.id"><td>{{ job.status }}<span class="cell-subtext">{{ job.created_at }}</span></td><td>{{ job.stage??'-' }}<span class="cell-subtext">{{ job.progress }}% {{ job.error?`· ${job.error}`:'' }}</span></td><td>{{ job.attempt }}</td><td><template v-if="job.status==='queued'"><button class="secondary-action" @click="runJob(job)">本次运行</button><button class="secondary-action" @click="changeJob(job,'cancel')">取消</button></template><button v-else-if="job.status==='failed'||job.status==='cancelled'" class="secondary-action" @click="changeJob(job,'retry')">重试</button><span v-else>-</span></td></tr></tbody></table><div v-else class="empty-project">尚无 SAST Job。</div></div><div class="panel full"><div class="panel-header"><h2>项目质量门禁</h2><span>按分支、等级、新问题和规则例外计算</span></div><div v-if="profile" class="filter-grid"><label>阻断等级<select v-model="profile.quality_gate.threshold"><option v-for="item in ['critical','high','medium','low','info','none']" :key="item">{{ item }}</option></select></label><label>分支 glob<input :value="profile.quality_gate.branch_patterns?.join(',')" @input="profile.quality_gate.branch_patterns=($event.target as HTMLInputElement).value.split(',')" /></label><label>排除规则 ID<input :value="profile.quality_gate.excluded_rule_ids?.join(',')" @input="profile.quality_gate.excluded_rule_ids=($event.target as HTMLInputElement).value.split(',')" /></label><label class="inline-check"><input v-model="profile.quality_gate.enabled" type="checkbox"/>启用门禁</label><label class="inline-check"><input v-model="profile.quality_gate.block_new_only" type="checkbox"/>只阻断新增问题</label><button class="secondary-action" @click="saveProfile">保存门禁</button></div><div v-if="message" class="empty-project">{{ message }}</div></div></section></div></details>
  <details class="advanced-details governance-advanced-details" open><summary>SAST 语义分析、Git 基线与交付门禁</summary><div class="advanced-details-body"><section class="content-grid"><div class="panel full"><div class="panel-header"><h2>受限语义分析</h2><span>Python AST + 直接本地跨函数数据流；JS/TS 为保守本地数据流</span></div><p>覆盖 SQL、命令执行、SSRF、路径穿越和不安全反序列化的 Source → Sink → Sanitizer 检查。结果是可复核的静态线索，不等同于全程序可达性或可利用性证明。</p><div v-if="profile" class="filter-grid"><label>Git 基线 revision<input v-model="profile.git_baseline_ref" placeholder="例如 origin/main 或 HEAD~1"/></label><label class="inline-check"><input v-model="profile.scan_git_history_secrets" type="checkbox"/>扫描 Git 历史中的密钥标识（仅保存路径）</label><label class="inline-check"><input v-model="profile.changed_files_only" type="checkbox"/>仅扫描基线差异文件</label><button class="secondary-action" @click="saveProfile">保存基线配置</button></div></div><div class="panel"><div class="panel-header"><h2>质量门禁</h2><span>{{ report?.quality_gate?.status??'等待扫描' }}</span></div><div class="kv-list"><div><span>阈值</span><strong>{{ report?.quality_gate?.threshold??'high' }}</strong></div><div><span>阻断 Finding</span><strong>{{ report?.quality_gate?.blocking_finding_count??0 }}</strong></div><div><span>本次扫描</span><strong>{{ report?.summary?.finding_count??0 }}</strong></div></div></div><div class="panel"><div class="panel-header"><h2>Git 证据</h2><span>{{ report?.git?.available?'已关联':'等待 Git 项目扫描' }}</span></div><div class="kv-list"><div><span>基线</span><strong>{{ report?.git?.baseline_ref??'未设置' }}</strong></div><div><span>差异文件</span><strong>{{ report?.git?.changed_files?.length??0 }}</strong></div><div><span>历史密钥路径</span><strong>{{ report?.git?.history_secret_count??0 }}</strong></div></div></div></section></div></details>
  <details class="advanced-details governance-advanced-details"><summary>Semgrep 规则发布与真实引擎预检</summary><div class="advanced-details-body"><section class="content-grid"><div class="panel full"><div class="panel-header"><h2>规则包生命周期</h2><span>draft / published / archived；发布后的包才会实际进入 Semgrep 扫描</span></div><table v-if="rules.length"><thead><tr><th>名称</th><th>状态</th><th>审批</th><th>操作</th></tr></thead><tbody><tr v-for="pack in rules" :key="pack.id"><td>{{ pack.name }}<span class="cell-subtext">{{ pack.rule_ids?.join(', ') }}</span></td><td>{{ pack.status }}</td><td>{{ pack.approved_by??'未记录' }}</td><td><button class="secondary-action" @click="preflight(pack)">真实引擎预检</button><button v-if="pack.status!=='published'" class="secondary-action" @click="publish(pack)">发布</button></td></tr></tbody></table><div v-else class="empty-project">先在“语义分析、Git 基线与交付门禁”区域创建 YAML 规则包。</div></div></section></div></details>
  <details class="advanced-details governance-advanced-details" open><summary>项目 Semgrep YAML 规则包</summary><div class="advanced-details-body"><section class="panel full"><div class="panel-header"><h2>草稿、校验、发布与离线执行</h2><span>发布后的规则包才参与扫描</span></div><div class="filter-grid"><label>规则包名称<input v-model="packDraft.name" /></label><label>保存状态<select v-model="packDraft.status"><option value="draft">草稿（不扫描）</option><option value="published">直接发布</option></select></label><label class="wide-field">YAML<textarea v-model="packDraft.content" rows="9" /></label><button class="secondary-action" @click="validatePack">校验 YAML</button><button class="primary-action" @click="savePack">{{ packDraft.status==='draft'?'保存草稿':'发布规则包' }}</button></div></section></div></details>
  <details class="advanced-details governance-advanced-details"><summary>修复草案与回归扫描（仅供人工评审）</summary><div class="advanced-details-body"><section class="content-grid"><div class="panel full"><div class="panel-header"><h2>高风险 Finding 修复草案</h2><span>不会写入源码、不会创建 PR，也不会自动执行回归</span></div><table v-if="store.findings.filter(i=>i.source==='SAST'&&['critical','high'].includes(i.severity)).length"><thead><tr><th>等级</th><th>Finding</th><th>位置</th><th>操作</th></tr></thead><tbody><tr v-for="item in store.findings.filter(i=>i.source==='SAST'&&['critical','high'].includes(i.severity)).slice(0,8)" :key="item.id"><td><span class="severity" :class="item.severity">{{ item.severity }}</span></td><td>{{ item.title }}<span class="cell-subtext">{{ item.rule_id }}</span></td><td>{{ item.file_path??'项目级' }}:{{ item.line_start??'-' }}</td><td><button class="secondary-action" @click="loadFixDraft(item.id)">生成评审草案</button></td></tr></tbody></table><div v-else class="empty-project">先执行 SAST；出现 critical/high Finding 后可生成不落盘的修复草案。</div></div><div v-if="fixDraft" class="panel full"><div class="panel-header"><h2>草案：{{ fixDraft.category }}</h2><span>{{ fixDraft.status }}</span></div><p>{{ fixDraft.recommended_change }}</p><pre class="code-preview">{{ fixDraft.patch }}</pre><p>{{ fixDraft.limitations?.join(' ') }}</p></div></section></div></details>
  <details class="advanced-details governance-advanced-details"><summary>SAST 规则、离线 CI 与引擎治理</summary><div class="advanced-details-body"><section class="content-grid"><div class="panel full"><div class="panel-header"><h2>扫描配置与规则版本</h2><span>配置 v{{ profile?.profile_version??'-' }} · 本地规则包 {{ profile?.rule_pack_version??'-' }}</span></div><div v-if="profile" class="filter-grid"><label>Semgrep 规则包 / 本地配置<input v-model="profile.semgrep_config" /></label><label class="inline-check"><input v-model="profile.semgrep_enabled" type="checkbox"/>启用 Semgrep</label><label class="inline-check"><input v-model="profile.include_local_rules" type="checkbox"/>启用本地规则</label><label class="inline-check"><input v-model="profile.clear_previous" type="checkbox"/>新扫描关闭旧活动 Finding</label><button class="secondary-action" @click="saveProfile">保存</button><button class="secondary-action" @click="exportCiConfig">导出 CI 配置</button></div></div><div class="panel"><div class="panel-header"><h2>固定版 Semgrep</h2><span>{{ toolHealth?.can_run_semgrep?'可用':'离线降级' }}</span></div><div class="kv-list"><div><span>CLI</span><strong>{{ toolHealth?.semgrep_cli?.version??'未检测到' }}</strong></div><div><span>Docker 镜像</span><strong>{{ toolHealth?.docker_image?.image??'-' }}</strong></div><div><span>镜像状态</span><strong>{{ toolHealth?.docker_image?.available?'本地已准备':'未下载' }}</strong></div></div></div><div class="panel"><div class="panel-header"><h2>扫描差异</h2><span>{{ diff?.base_scan_id?'与上一批次比较':'等待第二次扫描' }}</span></div><div class="kv-list"><div><span>新增</span><strong>{{ diff?.summary?.added??0 }}</strong></div><div><span>消失</span><strong>{{ diff?.summary?.removed??0 }}</strong></div><div><span>等级变化</span><strong>{{ diff?.summary?.severity_changed??0 }}</strong></div><div><span>历史批次</span><strong>{{ history.length }}</strong></div></div></div><div class="panel full"><div class="panel-header"><h2>项目自定义规则</h2><span>正则规则会在本地 SAST 引擎中实际运行</span></div><div class="filter-grid"><label>规则 ID<input v-model="customDraft.rule_id" /></label><label>标题<input v-model="customDraft.title" /></label><label>等级<select v-model="customDraft.severity"><option v-for="i in ['critical','high','medium','low','info']" :key="i">{{ i }}</option></select></label><label>分类<input v-model="customDraft.category" /></label><label>文件后缀<input v-model="customDraft.file_extensions" /></label><label>正则模式<input v-model="customDraft.pattern" /></label><label>命中样例<textarea v-model="customDraft.test_sample" /></label><label>说明<input v-model="customDraft.description" /></label><label>修复建议<input v-model="customDraft.remediation" /></label><button class="secondary-action" @click="validateCustomRule">校验 / 预览</button><button class="primary-action" @click="createCustomRule">保存并启用</button></div><table v-if="profile?.custom_rules?.length"><tbody><tr v-for="rule in profile.custom_rules" :key="rule.id"><td>{{ rule.rule_id }} v{{ rule.version }}</td><td>{{ rule.title }}</td><td>{{ rule.file_extensions?.join(', ') }}</td><td><button @click="toggleCustomRule(rule)">{{ rule.enabled?'停用':'启用' }}</button></td></tr></tbody></table></div></section></div></details>
  <section class="metric-grid"><article class="metric-card"><span>SAST 发现</span><strong>{{ store.findings.filter(i => i.source === 'SAST').length }}</strong></article><article class="metric-card"><span>严重 / 高危</span><strong>{{ store.findings.filter(i => i.source === 'SAST' && ['critical','high'].includes(String(i.severity).toLowerCase())).length }}</strong></article><article class="metric-card"><span>扫描批次</span><strong>{{ history.length }}</strong></article><article class="metric-card"><span>规则包</span><strong>{{ rules.length }}</strong></article></section>
  <section class="panel"><div class="panel-header"><h2>SAST 扫描</h2><span>{{ store.moduleStatus.sast }} · {{ toolHealth?.status ?? toolHealth?.overall_status ?? "工具状态未检查" }}</span></div><div class="toolbar"><label>SAST 独立源码路径<input v-model="store.sastPath" /></label><button class="primary-action" :disabled="store.moduleLoading.sast" @click="store.scan('sast').then(load)">{{ store.moduleLoading.sast?'扫描中':'开始扫描并复测' }}</button><button class="secondary-action" :disabled="store.moduleLoading.sast" @click="store.runSastReview">Sub-agent 复核</button><button class="secondary-action" @click="exportSarif">导出 SARIF</button></div></section>
  <section class="panel"><div class="panel-header"><h2>静态审计发现</h2><span>支持整改闭环</span></div><DataTable :rows="store.findings.filter(i => i.source === 'SAST')" :columns="findingColumns" /></section>
  <p class="helper-text">{{ message }}</p>
</div></template>
